import{describe,it,expect}from"vitest";import{dynasties}from"../../history/dynasties/data.js";describe("Dynasty explorer integration",()=>{it("exposes a dedicated Maurya explorer link on the dynasties landing data",()=>{const e=dynasties.find(e=>"maurya"===e.id);expect(e).toBeDefined(),expect(e.explorerPath).toBe("../Maurya Dynasty/MauryaDynasty.html"),expect(e.explorerLabel).toBe("Open Maurya Explorer")}),it("exposes a dedicated Gupta explorer link on the dynasties landing data",()=>{const e=dynasties.find(e=>"gupta"===e.id);expect(e).toBeDefined(),expect(e.explorerPath).toBe("../Gupta Dynasty/GuptaDynasty.html"),expect(e.explorerLabel).toBe("Open Gupta Explorer")})});